//! Materialise and compare recordings of the fixed Tier C corpus.
//!
//! The corpus lives in `pcx_play::fuzz_corpus` and is generated by
//! `pcx_play::fuzz_scenario`. Until now it was reachable only from the
//! library's own tests, so no two builds could be compared over it. This
//! command gives it a command-line surface:
//!
//! - `record` writes every corpus entry's generated RPL and the trace that
//!   entry produced into a directory, one file per entry.
//! - `compare` reads two such recordings and reports each entry, filing a
//!   divergence in the tracker-ready form `pcx_play::fuzz_report` produces.
//!
//! Harness convention, not game behavior. The corpus is synthetic: it is not
//! the original client, its RNG, its unit composition or its terrain, and a
//! divergence between two recordings says that the two builds differ over
//! this harness's inputs. It says nothing about Warcraft III parity.

#[cfg(not(target_arch = "wasm32"))]
fn main() -> std::process::ExitCode {
    match execute() {
        Ok(()) => std::process::ExitCode::SUCCESS,
        Err((code, message)) => {
            eprintln!("pcx-corpus: {message}");
            std::process::ExitCode::from(code)
        }
    }
}
#[cfg(target_arch = "wasm32")]
fn main() {}

#[cfg(not(target_arch = "wasm32"))]
fn usage() -> String {
    "usage: pcx-corpus record <output-dir> | pcx-corpus compare <left-dir> <right-dir> <filings-out>"
        .to_string()
}

#[cfg(not(target_arch = "wasm32"))]
fn execute() -> Result<(), (u8, String)> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        Some("record") => record(&args[1..]),
        Some("compare") => compare(&args[1..]),
        _ => Err((2, usage())),
    }
}

/// The RPL file name of one corpus entry.
#[cfg(not(target_arch = "wasm32"))]
fn rpl_name(seed: u64, index: usize) -> String {
    format!("s{seed}-{index}.rpl")
}

/// The trace file name of one corpus entry.
#[cfg(not(target_arch = "wasm32"))]
fn trace_name(seed: u64, index: usize) -> String {
    format!("s{seed}-{index}.trace")
}

/// Writes every corpus entry's RPL and trace into `directory`.
///
/// The recording is the corpus recipe's own output: the same recipe and the
/// same seed produce the same bytes, so two recordings of two builds differ
/// only where the builds differ.
#[cfg(not(target_arch = "wasm32"))]
fn record(args: &[String]) -> Result<(), (u8, String)> {
    use pcx_play::fuzz_corpus::{CORPUS_RECIPE_VERSION, corpus_entries};
    use pcx_play::fuzz_scenario::{default_domains, default_limits, generate_one};

    if args.len() != 1 {
        return Err((2, usage()));
    }
    let directory = std::path::Path::new(&args[0]);
    std::fs::create_dir_all(directory).map_err(|e| (2, format!("{}: {e}", directory.display())))?;
    let domains = default_domains();
    let limits = default_limits();
    let entries = corpus_entries();
    for (index, entry) in entries.iter().enumerate() {
        let (rpl, _) = generate_one(
            entry.seed,
            index,
            entry.ticks,
            entry.units,
            entry.actions,
            &domains,
            limits,
        )
        .map_err(|e| (2, format!("entry {index}: {e}")))?;
        let parsed = pcx_play::Rpl::parse(&rpl).map_err(|e| (2, format!("entry {index}: {e}")))?;
        let trace = parsed
            .run()
            .map_err(|e| (2, format!("entry {index}: {e}")))?;
        write_file(directory, &rpl_name(entry.seed, index), rpl.as_bytes())?;
        write_file(directory, &trace_name(entry.seed, index), &trace.encode())?;
        println!(
            "entry={index} seed={} hash={:016x}",
            entry.seed,
            trace.canonical_hash()
        );
    }
    println!("recipe={CORPUS_RECIPE_VERSION} entries={}", entries.len());
    Ok(())
}

/// Compares two recordings of the fixed corpus.
///
/// Every entry is reported on stdout, one line each. A divergence is also
/// filed into `filings_out` in the tracker-ready form, which names the seed,
/// the recipe, both trace hashes and the artifact name of the scenario.
#[cfg(not(target_arch = "wasm32"))]
fn compare(args: &[String]) -> Result<(), (u8, String)> {
    use pcx_play::fuzz_corpus::corpus_entries;
    use pcx_play::fuzz_report::{DivergenceFiling, format_tracker_entry};

    if args.len() != 3 {
        return Err((2, usage()));
    }
    let left_dir = std::path::Path::new(&args[0]);
    let right_dir = std::path::Path::new(&args[1]);
    let filings_out = std::path::Path::new(&args[2]);
    let entries = corpus_entries();
    let mut filings = String::new();
    let mut diverged = 0usize;
    for (index, entry) in entries.iter().enumerate() {
        // The baseline's scenario is read first, so a recording that is
        // missing its RPL is refused before any entry is reported rather
        // than only when a divergence needs the filing.
        let rpl = read_text(left_dir, &rpl_name(entry.seed, index))?;
        let left = read_trace(left_dir, entry.seed, index)?;
        let right = read_trace(right_dir, entry.seed, index)?;
        match pcx_play::first_divergence(&left, &right) {
            None => println!("entry={index} seed={} unchanged", entry.seed),
            Some(divergence) => {
                diverged += 1;
                println!("entry={index} seed={} diverge {divergence}", entry.seed);
                // The filing quotes the baseline's scenario, because that is
                // the one a reader reproduces against the candidate.
                filings.push_str(&format_tracker_entry(&DivergenceFiling {
                    scenario: &left.header.scenario,
                    map: &left.header.map,
                    seed: entry.seed,
                    corpus_index: index,
                    rpl: &rpl,
                    divergence: &divergence,
                    left: &left,
                    right: &right,
                }));
            }
        }
    }
    write_path(filings_out, filings.as_bytes()).map_err(|e| (2, e))?;
    println!("entries={} diverged={diverged}", entries.len());
    if diverged > 0 {
        // The report is on stdout; the filing is in the named file. A
        // divergence is a result, not a usage error, so nothing is printed on
        // stderr and the exit code carries the verdict.
        std::process::exit(1);
    }
    Ok(())
}

#[cfg(not(target_arch = "wasm32"))]
fn write_file(directory: &std::path::Path, name: &str, bytes: &[u8]) -> Result<(), (u8, String)> {
    write_path(&directory.join(name), bytes).map_err(|e| (2, e))
}

#[cfg(not(target_arch = "wasm32"))]
fn write_path(path: &std::path::Path, bytes: &[u8]) -> Result<(), String> {
    std::fs::write(path, bytes).map_err(|e| format!("{}: {e}", path.display()))
}

#[cfg(not(target_arch = "wasm32"))]
fn read_bytes(directory: &std::path::Path, name: &str) -> Result<Vec<u8>, (u8, String)> {
    let path = directory.join(name);
    std::fs::read(&path).map_err(|e| (2, format!("{}: {e}", path.display())))
}

#[cfg(not(target_arch = "wasm32"))]
fn read_text(directory: &std::path::Path, name: &str) -> Result<String, (u8, String)> {
    let bytes = read_bytes(directory, name)?;
    String::from_utf8(bytes).map_err(|_| {
        (
            2,
            format!("{}: not valid UTF-8", directory.join(name).display()),
        )
    })
}

#[cfg(not(target_arch = "wasm32"))]
fn read_trace(
    directory: &std::path::Path,
    seed: u64,
    index: usize,
) -> Result<pcx_play::Trace, (u8, String)> {
    let name = trace_name(seed, index);
    let bytes = read_bytes(directory, &name)?;
    pcx_play::Trace::decode(&bytes)
        .map_err(|e| (2, format!("{}: {e}", directory.join(&name).display())))
}
